  tm_272: "أهلاً بك في **MATRIX AI Assistant**! 📊\n\nأنا مساعدك التحليلي الذكي المتقدم للأسواق المالية. يمكنني مساعدتك في تحليل أزواج العملات، شرح استراتيجيات SMC وICT، قراءة المؤشرات الفنية، أو حساب إدارة المخاطر لحسابك.\n\nالزوج النشط حالياً: **{sym}** (سعر العرض: {bid} | الفارق: {spread} نقطة). بماذا يمكنني مساعدتك اليوم؟",
